// spec-audit: owner=deg,den,e,fName,lim,num,sub,sup
pub(crate) fn patch_o_math_arg(
    w: &mut Writer<'_>,
    el: &Elem,
    b: Option<&m::OMathArg>,
    a: &m::OMathArg,
) -> R {
    const ORDER: &[&str] = &[
        "argPr",
        "acc",
        "bar",
        "box",
        "borderBox",
        "d",
        "eqArr",
        "f",
        "func",
        "groupChr",
        "limLow",
        "limUpp",
        "m",
        "nary",
        "phant",
        "rad",
        "sPre",
        "sSub",
        "sSubSup",
        "sSup",
        "r",
        "ctrlPr",
    ];
    w.sync_child(
        el,
        NS_M,
        "m",
        ORDER,
        "argPr",
        b.and_then(|b| b.arg_pr.as_deref()),
        a.arg_pr.as_deref(),
        patch_o_math_arg_pr,
    )?;
    w.sync_child(
        el,
        NS_M,
        "m",
        ORDER,
        "ctrlPr",
        b.and_then(|b| b.ctrl_pr.as_deref()),
        a.ctrl_pr.as_deref(),
        patch_ctrl_pr,
    )?;
    sync_items(
        w,
        el,
        ORDER,
        &[
            (NS_M, "m", "acc"),
            (NS_M, "m", "bar"),
            (NS_M, "m", "box"),
            (NS_M, "m", "borderBox"),
            (NS_M, "m", "d"),
            (NS_M, "m", "eqArr"),
            (NS_M, "m", "f"),
            (NS_M, "m", "func"),
            (NS_M, "m", "groupChr"),
            (NS_M, "m", "limLow"),
            (NS_M, "m", "limUpp"),
            (NS_M, "m", "m"),
            (NS_M, "m", "nary"),
            (NS_M, "m", "phant"),
            (NS_M, "m", "rad"),
            (NS_M, "m", "sPre"),
            (NS_M, "m", "sSub"),
            (NS_M, "m", "sSubSup"),
            (NS_M, "m", "sSup"),
            (NS_M, "m", "r"),
        ],
        b.map_or(&[], |b| b.items.as_slice()),
        &a.items,
        o_math_arg_item_name,
        patch_o_math_arg_item,
    )?;
    let _ = (&b, &a);
    Ok(())
}

fn o_math_arg_item_name(
    i: &m::OMathArgItem,
) -> (&'static [&'static str], &'static str, &'static str) {
    match i {
        m::OMathArgItem::Acc(_) => (NS_M, "m", "acc"),
        m::OMathArgItem::Bar(_) => (NS_M, "m", "bar"),
        m::OMathArgItem::Box(_) => (NS_M, "m", "box"),
        m::OMathArgItem::BorderBox(_) => (NS_M, "m", "borderBox"),
        m::OMathArgItem::D(_) => (NS_M, "m", "d"),
        m::OMathArgItem::EqArr(_) => (NS_M, "m", "eqArr"),
        m::OMathArgItem::F(_) => (NS_M, "m", "f"),
        m::OMathArgItem::Func(_) => (NS_M, "m", "func"),
        m::OMathArgItem::GroupChr(_) => (NS_M, "m", "groupChr"),
        m::OMathArgItem::LimLow(_) => (NS_M, "m", "limLow"),
        m::OMathArgItem::LimUpp(_) => (NS_M, "m", "limUpp"),
        m::OMathArgItem::M(_) => (NS_M, "m", "m"),
        m::OMathArgItem::Nary(_) => (NS_M, "m", "nary"),
        m::OMathArgItem::Phant(_) => (NS_M, "m", "phant"),
        m::OMathArgItem::Rad(_) => (NS_M, "m", "rad"),
        m::OMathArgItem::SPre(_) => (NS_M, "m", "sPre"),
        m::OMathArgItem::SSub(_) => (NS_M, "m", "sSub"),
        m::OMathArgItem::SSubSup(_) => (NS_M, "m", "sSubSup"),
        m::OMathArgItem::SSup(_) => (NS_M, "m", "sSup"),
        m::OMathArgItem::R(_) => (NS_M, "m", "r"),
    }
}

