// spec-audit: owner=oMath
pub(crate) fn patch_o_math(w: &mut Writer<'_>, el: &Elem, b: Option<&m::OMath>, a: &m::OMath) -> R {
    const ORDER: &[&str] = &[
        "acc",
        "bar",
        "box",
        "borderBox",
        "d",
        "eqArr",
        "f",
        "func",
        "groupChr",
        "limLow",
        "limUpp",
        "m",
        "nary",
        "phant",
        "rad",
        "sPre",
        "sSub",
        "sSubSup",
        "sSup",
        "r",
    ];
    sync_items(
        w,
        el,
        ORDER,
        &[
            (NS_M, "m", "acc"),
            (NS_M, "m", "bar"),
            (NS_M, "m", "box"),
            (NS_M, "m", "borderBox"),
            (NS_M, "m", "d"),
            (NS_M, "m", "eqArr"),
            (NS_M, "m", "f"),
            (NS_M, "m", "func"),
            (NS_M, "m", "groupChr"),
            (NS_M, "m", "limLow"),
            (NS_M, "m", "limUpp"),
            (NS_M, "m", "m"),
            (NS_M, "m", "nary"),
            (NS_M, "m", "phant"),
            (NS_M, "m", "rad"),
            (NS_M, "m", "sPre"),
            (NS_M, "m", "sSub"),
            (NS_M, "m", "sSubSup"),
            (NS_M, "m", "sSup"),
            (NS_M, "m", "r"),
        ],
        b.map_or(&[], |b| b.items.as_slice()),
        &a.items,
        o_math_item_name,
        patch_o_math_item,
    )?;
    let _ = (&b, &a);
    Ok(())
}

fn o_math_item_name(i: &m::OMathItem) -> (&'static [&'static str], &'static str, &'static str) {
    match i {
        m::OMathItem::Acc(_) => (NS_M, "m", "acc"),
        m::OMathItem::Bar(_) => (NS_M, "m", "bar"),
        m::OMathItem::Box(_) => (NS_M, "m", "box"),
        m::OMathItem::BorderBox(_) => (NS_M, "m", "borderBox"),
        m::OMathItem::D(_) => (NS_M, "m", "d"),
        m::OMathItem::EqArr(_) => (NS_M, "m", "eqArr"),
        m::OMathItem::F(_) => (NS_M, "m", "f"),
        m::OMathItem::Func(_) => (NS_M, "m", "func"),
        m::OMathItem::GroupChr(_) => (NS_M, "m", "groupChr"),
        m::OMathItem::LimLow(_) => (NS_M, "m", "limLow"),
        m::OMathItem::LimUpp(_) => (NS_M, "m", "limUpp"),
        m::OMathItem::M(_) => (NS_M, "m", "m"),
        m::OMathItem::Nary(_) => (NS_M, "m", "nary"),
        m::OMathItem::Phant(_) => (NS_M, "m", "phant"),
        m::OMathItem::Rad(_) => (NS_M, "m", "rad"),
        m::OMathItem::SPre(_) => (NS_M, "m", "sPre"),
        m::OMathItem::SSub(_) => (NS_M, "m", "sSub"),
        m::OMathItem::SSubSup(_) => (NS_M, "m", "sSubSup"),
        m::OMathItem::SSup(_) => (NS_M, "m", "sSup"),
        m::OMathItem::R(_) => (NS_M, "m", "r"),
    }
}

