/// Bring a standalone element of `math` from one state to another.
// spec-audit: m:<mathPr>
// spec-audit: m:<oMathPara>
// spec-audit: m:<oMath>
pub(crate) fn patch_root(w: &mut Writer<'_>, el: &Elem, b: Option<&m::Root>, a: &m::Root) -> R {
    match a {
        m::Root::MathPr(a) => patch_math_pr(
            w,
            el,
            match b {
                Some(m::Root::MathPr(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::OMathPara(a) => patch_o_math_para(
            w,
            el,
            match b {
                Some(m::Root::OMathPara(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
        m::Root::OMath(a) => patch_o_math(
            w,
            el,
            match b {
                Some(m::Root::OMath(b)) => Some(&**b),
                _ => None,
            },
            a,
        ),
    }
}
